<script>
/* ─── Mega-Menu Dropdowns ─── */
(function() {
  const navTriggers = document.querySelectorAll('.nav-trigger');
  const megaMenus = document.querySelectorAll('.mega-menu');
  let activeMenu = null;

  function closeAll() {
    navTriggers.forEach(t => { t.classList.remove('active'); t.setAttribute('aria-expanded', 'false'); });
    megaMenus.forEach(m => m.classList.remove('visible'));
    activeMenu = null;
  }

  navTriggers.forEach(trigger => {
    trigger.addEventListener('click', function(e) {
      e.stopPropagation();
      const menuName = this.dataset.menu;
      const menu = document.querySelector(`.mega-menu[data-menu="${menuName}"]`);
      if (activeMenu === menuName) { closeAll(); return; }
      closeAll();
      this.classList.add('active');
      this.setAttribute('aria-expanded', 'true');
      if (menu) menu.classList.add('visible');
      activeMenu = menuName;
    });
  });

  document.addEventListener('click', function(e) {
    if (!e.target.closest('.main-nav')) closeAll();
  });

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeAll();
  });
})();

/* ─── Mobile Navigation ─── */
(function() {
  const mobileBtn = document.getElementById('mobileMenuBtn');
  const mobileNav = document.getElementById('mobileNav');
  const mobileTriggers = document.querySelectorAll('.mobile-nav-trigger');

  mobileBtn.addEventListener('click', function() {
    const isOpen = mobileNav.classList.toggle('open');
    this.setAttribute('aria-expanded', isOpen);
    document.body.style.overflow = isOpen ? 'hidden' : '';
  });

  mobileTriggers.forEach(trigger => {
    trigger.addEventListener('click', function() {
      const menuName = this.dataset.mobile;
      const links = document.querySelector(`.mobile-nav-links[data-mobile="${menuName}"]`);
      this.classList.toggle('open');
      if (links) links.classList.toggle('open');
    });
  });
})();

/* ─── Health Topics Carousel ─── */
(function() {
  const track = document.getElementById('topicsTrack');
  const prevBtn = document.getElementById('topicsPrev');
  const nextBtn = document.getElementById('topicsNext');
  let scrollPos = 0;

  function getCardWidth() {
    const card = track.querySelector('.topic-card');
    if (!card) return 200;
    return card.offsetWidth + parseInt(getComputedStyle(track).gap || 24);
  }

  function getMaxScroll() {
    return track.scrollWidth - track.parentElement.offsetWidth;
  }

  function updateButtons() {
    const max = getMaxScroll();
    prevBtn.disabled = scrollPos <= 0;
    nextBtn.disabled = scrollPos >= max - 1;
  }

  prevBtn.addEventListener('click', function() {
    scrollPos = Math.max(0, scrollPos - getCardWidth() * 2);
    track.style.transform = `translateX(-${scrollPos}px)`;
    updateButtons();
  });

  nextBtn.addEventListener('click', function() {
    const max = getMaxScroll();
    scrollPos = Math.min(max, scrollPos + getCardWidth() * 2);
    track.style.transform = `translateX(-${scrollPos}px)`;
    updateButtons();
  });

  window.addEventListener('resize', function() {
    const max = getMaxScroll();
    if (scrollPos > max) scrollPos = max;
    track.style.transform = `translateX(-${scrollPos}px)`;
    updateButtons();
  });

  updateButtons();
})();

