      { title: 'Eczema Solutions: Knowledge for Self-Care', meta: 'Skin Care &bull; 7 min read' },
      { title: 'The Truth About Hyaluronic Acid and Moisturizers', meta: 'Skin Care &bull; 6 min read' },
      { title: 'Sunscreen 101: What SPF Do You Really Need?', meta: 'Skin Care &bull; 5 min read' },
      { title: 'Understanding Retinoids: Benefits and Side Effects', meta: 'Skin Care &bull; 9 min read' },
      { title: 'Winter Skin Care Routine: Expert Tips', meta: 'Skin Care &bull; 6 min read' }
    ]
  };

  const tabsContainer = document.getElementById('readsTabs');
  const articlesGrid = document.getElementById('articlesGrid');
  const tabBtns = tabsContainer.querySelectorAll('.tab-btn');

  function renderArticles(tabId) {
    const articles = articlesData[tabId] || articlesData['top-reads'];
    articlesGrid.classList.add('switching');
    setTimeout(function() {
      articlesGrid.innerHTML = articles.map(function(a, i) {
        return '<a href="#" class="article-card">'
          + '<div class="article-thumb-placeholder"></div>'
          + '<div class="article-card-body">'
          + '<h4>' + a.title + '</h4>'
          + '<span class="article-meta">' + a.meta + '</span>'
          + '</div></a>';
      }).join('');
      articlesGrid.classList.remove('switching');
    }, 150);
  }

  tabBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      tabBtns.forEach(function(b) { b.classList.remove('active'); b.setAttribute('aria-selected', 'false'); });
      this.classList.add('active');
      this.setAttribute('aria-selected', 'true');
      renderArticles(this.dataset.tab);
    });
  });

  // Initial render
  renderArticles('top-reads');
})();

/* ─── Newsletter Forms ─── */
(function() {
  function setupNewsletter(formEl, feedbackEl) {
    if (!formEl) return;
    formEl.addEventListener('submit', function(e) {
      e.preventDefault();
      var emailInput = formEl.querySelector('input[type="email"]');
      var email = emailInput.value.trim();

      if (!email) {
        showFeedback(feedbackEl, 'Please enter your email address.', 'error');
        return;
      }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        showFeedback(feedbackEl, 'Please enter a valid email address.', 'error');
        return;
      }

      showFeedback(feedbackEl, 'Thank you! You\'ve been subscribed.', 'success');
      emailInput.value = '';
    });
  }

  function showFeedback(el, message, type) {
    if (!el) return;
    el.textContent = message;
    el.className = 'form-feedback ' + type;
    setTimeout(function() { el.className = 'form-feedback'; }, 4000);
  }

  setupNewsletter(
    document.getElementById('newsletterForm'),
    document.getElementById('formFeedback')
  );

  var footerForm = document.getElementById('footerNewsletter');
  if (footerForm) {
    footerForm.addEventListener('submit', function(e) {
      e.preventDefault();
      var input = footerForm.querySelector('input[type="email"]');
      var email = input.value.trim();
      if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        input.style.borderColor = '#DC2626';
        setTimeout(function() { input.style.borderColor = ''; }, 2000);
        return;
      }
      input.value = '';
      input.placeholder = 'Subscribed! Thank you.';
      input.style.borderColor = '#02838D';
      setTimeout(function() { input.placeholder = 'Your email address'; input.style.borderColor = ''; }, 3000);
    });
  }
})();
</script>

